package com.dayglance.app.launcher

import com.dayglance.app.data.CalendarRepository.CalEvent
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertSame
import org.junit.Test
import java.time.LocalDate

/**
 * The provider's own calendar read against the web layer's, through the shared
 * fixture (dayglance-ios/TestFixtures/launcherDeviceEvents.vectors.json, whose
 * expected rows are generated by src/utils/launcherDeviceEvents.fixture.test.js):
 * one event must be one row whichever side read it.
 */
class LauncherDeviceEventsTest {

    private val fixture = JSONObject(
        LauncherDeviceEventsTest::class.java.getResourceAsStream("/launcherDeviceEvents.vectors.json")!!.bufferedReader().readText()
    )

    private fun event(o: JSONObject) = CalEvent(
        id = o.getString("id"), title = o.getString("title"), start = o.getString("start"), end = o.getString("end"),
        allDay = o.getBoolean("allDay"), notes = o.getString("notes"), location = o.getString("location"),
        calendarId = o.getString("calendarId"), calendarName = o.getString("calendarName"), color = o.getString("color"),
    )

    private fun reader(events: JSONObject): (LocalDate) -> List<CalEvent> = { date ->
        val arr = events.optJSONArray(date.toString()) ?: JSONArray()
        (0 until arr.length()).map { event(arr.getJSONObject(it)) }
    }

    /** Key order and number boxing aside, the same JSON. */
    private fun normalised(o: JSONObject): Map<String, Any?> = JSONObject(o.toString()).toMap()

    @Test
    fun `the restore keywords are the web layer's`() {
        val arr = fixture.getJSONArray("restoreKeywords")
        assertEquals((0 until arr.length()).map { arr.getString(it) }.toSet(), LauncherDeviceEvents.RESTORE_KEYWORDS)
    }

    @Test
    fun `every fixture case reads to the rows the snapshot builds`() {
        val cases = fixture.getJSONArray("cases")
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            val config = LauncherDeviceEvents.config(JSONObject().put("deviceCalendar", c.getJSONObject("deviceCalendar")))!!
            val today = LocalDate.parse(c.getString("today"))
            val read = reader(c.getJSONObject("events"))
            val rows = LauncherDeviceEvents.rows(LauncherDeviceEvents.windowDates(today, config).map { it to read(it) }, config)
            val expected = c.getJSONArray("rows")
            assertEquals(c.getString("name"), (0 until expected.length()).map { normalised(expected.getJSONObject(it)) }, rows.map { normalised(it) })
        }
    }

    @Test
    fun `a live read replaces the snapshot's native rows and keeps every other row`() {
        val c = fixture.getJSONArray("cases").getJSONObject(0)
        val snapshot = JSONObject()
            .put("version", 1)
            .put("tasks", JSONArray()
                .put(JSONObject().put("id", "t1").put("native", false))
                .put(JSONObject().put("id", "native-cal-stale-2026-10-21").put("native", true)))
            .put("deviceCalendar", c.getJSONObject("deviceCalendar"))
        val out = JSONObject(LauncherDeviceEvents.withLiveEvents(snapshot.toString(), LocalDate.parse("2026-10-21"), reader(c.getJSONObject("events"))))
        val tasks = out.getJSONArray("tasks")
        val ids = (0 until tasks.length()).map { tasks.getJSONObject(it).getString("id") }
        assertEquals("t1", ids.first())
        assertEquals(false, "native-cal-stale-2026-10-21" in ids)
        assertEquals(c.getJSONArray("rows").length() + 1, ids.size)
    }

    @Test
    fun `a snapshot without the block, or one that does not parse, is served as it is`() {
        val plain = """{"version":1,"tasks":[{"id":"native-cal-1-2026-10-21","native":true}]}"""
        assertSame(plain, LauncherDeviceEvents.withLiveEvents(plain, LocalDate.parse("2026-10-21")) { error("not read") })
        assertSame("not json", LauncherDeviceEvents.withLiveEvents("not json", LocalDate.parse("2026-10-21")) { emptyList() })
    }

    @Test
    fun `energy is a restore keyword among the title's words, never a substring`() {
        assertEquals("restore", LauncherDeviceEvents.energy("Lunch with Sam"))
        assertEquals("restore", LauncherDeviceEvents.energy("#gym session"))
        assertEquals("effort", LauncherDeviceEvents.energy("Restaurant booking"))
    }
}
